    private void closeWalk(){if(walk!=null&&walk.stopForFallback())walk=null;}
    private void walk(LinearLayout card,String expectedRun,int expected){
        if(WalkFallbackSaved.chosen(Prefs.of(this),expectedRun,expected)){Design.text(card,"Math fallback",16,600,Design.INK);Design.space(card,12);math(card,expectedRun,expected);return;}
        Design.text(card,"Walk into your morning",22,600,Design.INK);Design.space(card,12);int target=position.task.targetSteps;
        int earned=expectedRun.equals(Prefs.text(this,"walkRun",""))&&Prefs.number(this,"walkUnit",-1)==expected?Prefs.number(this,"walkEarned",0):0;
        TextView count=Design.text(card,Math.max(0,Math.min(target,earned))+" / "+target+" steps",30,700,Design.INK);
        Design.text(card,"Carry your phone. Walk in a safe, clear space.",13,400,Design.MUTED);if(!resumed)return;
        // A failed unregister retains the old handle. Never allocate a replacement over uncertain cleanup.
        if(walk!=null){walkCleanup(card,walk,expectedRun,expected);walkFallback(card,walk,expectedRun,expected);return;}
        WalkSession.Port source;try{source=WalkPlatform.factory.create(this);}catch(RuntimeException unavailable){Design.text(card,"Step counting is unavailable. Solve math instead.",14,500,Design.MUTED);math(card,expectedRun,expected);return;}
        WalkSession[] owner={null};boolean[] cleanupShown={false};
        walk=new WalkSession(source,new WalkSession.Effects(){
            public boolean current(String run,int unit){return resumed&&walk==owner[0]&&run.equals(occurrence)&&unit==completed&&AlarmService.current(AlarmActivity.this,run);}
            public void progress(String run,int unit,int value){if(!current(run,unit))return;Prefs.of(AlarmActivity.this).edit().putString("walkRun",run).putInt("walkUnit",unit).putInt("walkEarned",value).apply();count.setText(value+" / "+target+" steps");}
            public void solved(String run,int unit){advance(run,unit);}
            public void unavailable(String run,int unit,WalkSession.State state){handler.post(()->{if(walk==owner[0]&&current(run,unit)){if(owner[0].cleanupPending()){if(!cleanupShown[0]){cleanupShown[0]=true;walkCleanup(card,owner[0],run,unit);}}else build();}});}
        },expectedRun,expected,target,earned);
        WalkSession session=walk;owner[0]=session;session.resume();if(walk!=session)return;
        if(session.cleanupPending()){walkCleanup(card,session,expectedRun,expected);walkFallback(card,session,expectedRun,expected);return;}
        String unavailable=switch(session.state()){case PERMISSION->"Physical activity access is off. Solve math instead.";case UNSUPPORTED->"This phone has no supported step sensor. Solve math instead.";case ERROR->"Step counting could not start. Solve math instead.";default->"";};
        if(!unavailable.isEmpty()){Design.space(card,12);Design.text(card,unavailable,14,500,Design.MUTED);math(card,expectedRun,expected);return;}
        walkFallback(card,session,expectedRun,expected);
    }
    private void walkCleanup(LinearLayout card,WalkSession session,String expectedRun,int expected){
        TextView error=Design.text(card,"Step cleanup could not finish. Earned steps are kept; retry before continuing.",14,500,Design.BROWN);
        error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
        Design.button(card,"Retry step cleanup",true,()->{
            if(!resumed||walk!=session||!card.isAttachedToWindow()||!hasWindowFocus()||!expectedRun.equals(occurrence)||expected!=completed||!AlarmService.current(this,expectedRun))return;
            if(!session.stopForFallback()){error.setText("Step cleanup is still pending. Retry before continuing.");return;}
            walk=null;build();
        });
    }
    private void walkFallback(LinearLayout card,WalkSession session,String expectedRun,int expected){
        TextView error=Design.text(card,"",13,500,0xffa93919);error.setVisibility(View.GONE);error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
        Design.button(card,"Use Math fallback",false,()->{
            WalkFallback.Result result=WalkFallback.choose(expectedRun,expected,new WalkFallback.Effects(){
                public boolean current(String run,int unit){return resumed&&walk==session&&run.equals(occurrence)&&unit==completed&&AlarmService.current(AlarmActivity.this,run);}
                public boolean stop(){return session.stopForFallback();}
                public boolean save(String run,int unit){return WalkFallbackSaved.save(Prefs.of(AlarmActivity.this),run,unit);}
            });
            if(result==WalkFallback.Result.CHOSEN){walk=null;selected=null;build();}
            else if(result!=WalkFallback.Result.STALE){error.setText(result==WalkFallback.Result.STOP_FAILED?"Step counting could not stop. Try again.":"Math fallback could not be saved. Try again.");error.setVisibility(View.VISIBLE);}
        });
    }
    private boolean registerShake(Sensor accelerometer){try{return sensors.registerListener(this,accelerometer,SensorManager.SENSOR_DELAY_GAME);}catch(RuntimeException unavailable){return false;}}
    private void restoreShakes(){shakes=occurrence.equals(Prefs.text(this,"challengeShakeRun",""))&&completed==Prefs.number(this,"challengeShakeUnit",-1)?Prefs.number(this,"challengeShakeCount",0):0;}
    private void advance(String expectedRun,int expected) {synchronized(Scheduler.class){if(!expectedRun.equals(occurrence))return;if(!AlarmService.current(this,expectedRun)){finish();return;}if(Prefs.number(this,"challengeCompleted",0)!=expected)return;int next=routine.advance(completed,expected);if(next==completed)return;completed=next;Prefs.of(this).edit().putInt("challengeCompleted",completed).putString("mathTask","").putString("retypeTask","").putInt("challengeShakeCount",0).putInt("challengeShakeUnit",completed).putString("challengeShakeRun",occurrence).apply();shakes=0;selected=null;if(routine.at(completed)==null)dismiss();else build();}}
    private boolean currentCognitive(String run,int unit){return resumed&&!isFinishing()&&!isDestroyed()&&hasWindowFocus()&&run.equals(occurrence)&&unit==completed&&Prefs.number(this,"challengeCompleted",0)==unit&&AlarmService.current(this,run);}
    private void closeCognitive(boolean remember){if(cognitive==null)return;if(remember&&!(cognitive instanceof WakeCognitiveTask.Retype))cognitiveState=cognitive.state();cognitive.close();cognitive=null;}
    private void memory(LinearLayout card,String expectedRun,int expected){cognitive=new WakeCognitiveTask.Memory(card,expectedRun,expected,random,cognitiveState,()->currentCognitive(expectedRun,expected),()->advance(expectedRun,expected));}
    private void sequence(LinearLayout card,String expectedRun,int expectedUnit){cognitive=new WakeCognitiveTask.Sequence(card,expectedRun,expectedUnit,position.round,random,cognitiveState,()->currentCognitive(expectedRun,expectedUnit),()->advance(expectedRun,expectedUnit));}
    static String hex(byte[] value) {StringBuilder b=new StringBuilder();for(byte x:value)b.append(String.format(Locale.ROOT,"%02X",x));return b.toString();}
    private void chooseSnooze(){if(!alarm.inputs.chooseSnooze||alarm.inputsInvalid){snooze();return;}if(snoozeDialog!=null&&snoozeDialog.isShowing())return;String run=occurrence;int used=Prefs.number(this,"snoozes_"+alarm.id,0);long remaining=SnoozeBudgets.remaining(this,alarm,run);if(remaining<=0||!AlarmInputs.canSnooze(AlarmService.current(this,run),used,alarm.snoozeLimit))return;SnoozeOffer offer=new SnoozeOffer(run,used,alarm.snoozeMinutes,alarm.shortenSnoozes,alarm.snoozeLimit,remaining);int[] choices=offer.values();boolean clock=SnoozeBudget.clockAvailable(System.currentTimeMillis(),java.time.ZoneId.systemDefault(),Math.min(remaining,SnoozePolicy.minutes(alarm.snoozeMinutes,alarm.shortenSnoozes,used)*60000L));if(choices.length==0&&!clock)return;String[] labels=new String[choices.length+(clock?1:0)];for(int n=0;n<choices.length;n++)labels[n]=choices[n]+" min";if(clock)labels[choices.length]="Until…";snoozeDialog=SleepPicker.choices(this,"Snooze for",labels,choices.length-1,n->{synchronized(Scheduler.class){long currentRemaining=SnoozeBudgets.remaining(this,alarm,occurrence);if(clock&&n==choices.length){if(offer.current(occurrence,Prefs.number(this,"snoozes_"+alarm.id,0),AlarmService.current(this,occurrence),resumed,alarm.snoozeLimit,currentRemaining))untilSnooze();return;}int minutes=offer.select(n,occurrence,Prefs.number(this,"snoozes_"+alarm.id,0),AlarmService.current(this,occurrence),resumed,alarm.snoozeLimit,alarm.snoozeMinutes,alarm.shortenSnoozes,currentRemaining);if(minutes>0)snooze(minutes);}});}
    private SnoozeUntil.State snoozeClockState(){try{String raw=Prefs.text(this,"active_alarm","{}");Alarm active=Alarm.read(new JSONObject(raw));long spent=SnoozeBudgets.spent(this,active.id,Prefs.text(this,"alarmRun",""));if(active.snoozeTotalMinutes==0&&!active.snoozeTotalInvalid)spent=Math.max(0,spent);return new SnoozeUntil.State(Prefs.text(this,"alarmRun",""),raw,Prefs.number(this,"snoozes_"+active.id,0),active.snoozeMinutes,active.shortenSnoozes,active.snoozeLimit,!active.inputsInvalid&&!active.snoozeTotalInvalid&&active.inputs.chooseSnooze,active.id==alarm.id&&AlarmService.current(this,occurrence),resumed,System.currentTimeMillis(),SystemClock.elapsedRealtime(),java.time.ZoneId.systemDefault(),active.snoozeTotalMinutes,spent);}catch(JSONException invalid){throw new IllegalArgumentException("Alarm settings changed. Reopen Snooze.");}}
    private void untilSnooze(){try{SnoozeUntil offer=new SnoozeUntil(snoozeClockState());snoozeDialog=SnoozeUntilDialog.show(this,offer,new SnoozeUntil.Port(){public SnoozeUntil.State state(){return snoozeClockState();}public void schedule(long deadline){synchronized(Scheduler.class){SnoozeUntil.State checked=snoozeClockState();int minute=java.time.Instant.ofEpochMilli(deadline).atZone(checked.zone).getHour()*60+java.time.Instant.ofEpochMilli(deadline).atZone(checked.zone).getMinute();if(offer.resolve(minute,checked)!=deadline)throw new IllegalArgumentException("Phone time changed. Reopen Snooze.");scheduleSnooze(checked.used,checked.wall,deadline);}}});}catch(IllegalArgumentException invalid){Ui.toast(this,invalid.getMessage());}}
    private void snooze(){snooze(SnoozePolicy.minutes(alarm.snoozeMinutes,alarm.shortenSnoozes,Prefs.number(this,"snoozes_"+alarm.id,0),SnoozeBudgets.remaining(this,alarm,occurrence)));}
    private void snooze(int minutes){synchronized(Scheduler.class){if(!AlarmService.current(this,occurrence)){finish();return;}int used=Prefs.number(this,"snoozes_"+alarm.id,0);if(!AlarmInputs.canSnooze(true,used,alarm.snoozeLimit)||!SnoozePolicy.accepts(minutes,alarm.snoozeMinutes,alarm.shortenSnoozes,used)||minutes*60000L>SnoozeBudgets.remaining(this,alarm,occurrence))return;try{long now=System.currentTimeMillis();scheduleSnooze(used,now,now+minutes*60000L);}catch(RuntimeException failure){Ui.toast(this,failure.getMessage()==null?"Snooze could not be scheduled. Alarm continues.":failure.getMessage());}}}
    private void scheduleSnooze(int used,long from,long deadline){if(!AlarmService.current(this,occurrence))throw new IllegalArgumentException("This alarm occurrence changed.");SnoozeBudgets.Reservation reservation=SnoozeBudgets.reserve(this,alarm,occurrence,used,from,deadline);try{Scheduler.at(this,alarm.id,Scheduler.SNOOZE,deadline);}catch(RuntimeException failure){if(!reservation.rollback())Prefs.put(this,"lastError","Snooze scheduling failed and its budget needs attention. Alarm continues.");throw failure;}if(AlarmService.current(this,occurrence))AwakeRuntime.snoozed(from,deadline);AlarmService.stop(this,occurrence);finish();}
    private void dismiss() {
        synchronized(Scheduler.class){if(!AlarmService.current(this,occurrence)){finish();return;}
        if(alarm.awakeCheck>0 && alarm.id>0) {
            if(!WakeChecks.arm(this,alarm,occurrence))Ui.toast(this,"Wake-up check needs attention. Open the check from Tonight.");
        }
        boolean completedDismissal=routine!=null&&routine.at(completed)==null;
        if(AlarmService.stop(this,occurrence)&&completedDismissal&&alarm.id>0)Automations.emit(this,AutomationEvent.Kind.ALARM_DISMISSED,occurrence);
        Naps.dismissed(this,alarm,alarm.awakeCheck>0);
        try { stopLockTask(); } catch(IllegalStateException ignored) {}
        startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();
        }
    }
    @Override public void onSensorChanged(SensorEvent e) {
        if(!resumed||position==null||!position.task.type.equals("Shake")||sensorExpected!=completed||!sensorRun.equals(occurrence)||e.timestamp<sensorArmedNanos)return;
        double mag=Math.sqrt(e.values[0]*e.values[0]+e.values[1]*e.values[1]+e.values[2]*e.values[2]);long now=SystemClock.elapsedRealtime();
        if(WakeShakeRule.accepts(mag,now,lastShake)) { lastShake=now;shakes++;progress.setVisibility(View.VISIBLE);progress.setText(shakes+" / "+target+" deliberate shakes");Prefs.of(this).edit().putString("challengeShakeRun",occurrence).putInt("challengeShakeUnit",completed).putInt("challengeShakeCount",shakes).apply();if(shakes>=target)advance(sensorRun,sensorExpected); }
    }
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(cognitive!=null){if(focused&&resumed)cognitive.resume();else cognitive.pause();}}
    @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}
